contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(string memory nm, string memory sym, uint256 maintRaw) public {
        require(maintRaw > 0 && maintRaw <= uint256(type(int256).max) / 1e18);

        UFixed18 maint = UFixed18.wrap(maintRaw);
        PayoffDefinition memory pd = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(uint8(0)),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(uint8(0)),
            data: bytes30(0)
        });
        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: nm,
            symbol: sym,
            payoffDefinition: pd,
            oracle: IOracleProvider(address(c)),
            maintenance: maint,
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: maint,
            utilizationCurve: curve
        });

        c.initialize(info);

        bool reverted;
        try c.initialize(info) { reverted = false; } catch { reverted = true; }

        assert(
            reverted &&
            keccak256(bytes(c.name())) == keccak256(bytes(nm)) &&
            keccak256(bytes(c.symbol())) == keccak256(bytes(sym)) &&
            UFixed18.unwrap(c.maintenance()) == maintRaw &&
            UFixed18.unwrap(c.makerLimit()) == maintRaw
        );
    }

    receive() external payable {}
}

