    function run(address account, UFixed18 amount) public {
        // c is freshly deployed and never initialized: the oracle and controller
        // are unset, so settling/reading versions cannot succeed and the
        // position-opening path must revert rather than mutate state.
        bool reverted;
        try c.openTakeFor(account, amount) { reverted = false; } catch { reverted = true; }

        // Observations via the public surface confirm the contract is unused:
        uint256 v = c.latestVersion();
        bool wasClosed = c.closed();

        assert(reverted && v == 0 && !wasClosed);
    }

    receive() external payable {}
}

